s=s.replace('from PIL import Image','from PIL import Image\nimport render_maps\nfrom native_labels import Decoder\n\nDUNGEONS = {151:"kamoshida",152:"kamoshida",153:"madarame",154:"kaneshiro",155:"futaba",156:"okumura",157:"niijima",159:"shido",162:"maruki"}')
s=s.replace("    maps, images, evidence, roots = [], {}, [], {}", "    decoder=Decoder(out/'tool/P5R_EFIGS.tsv')\n    def decode(raw):\n        label, unknown=decoder.decode(raw)\n        if unknown: raise ValueError('Titolo non decodificato')\n        return label\n    render_maps.text=decode\n    native_names, native_groups, _=render_maps.read_names(out)\n    maps, images, evidence, roots = [], {}, [], {}")
s=s.replace("        if city and status == 'riferimento-roadmap':", "        if major in DUNGEONS:\n            parent='dungeon-'+DUNGEONS[major]\n            assert len(native_groups[major])==1\n            parent_evidence={'kind':'native-dungeon-title','entity':DUNGEONS[major],'major':major,'nativeGroups':sorted(native_groups[major])}\n        elif city and status == 'riferimento-roadmap':")
s=s.replace("        maps.append(dict(chiave=key,", "        title_records=native_names.get((major,minor,layer),[])\n        native_titles=list(dict.fromkeys(r['title'] for r in title_records if r['title'] not in ('???','NULL','')))\n        title_from_texpack=len(native_titles)==1\n        if title_from_texpack: title=native_titles[0]\n        named=named or title_from_texpack\n        maps.append(dict(chiave=key,")
s=s.replace('            displayNameVerified=named,','            displayNameVerified=named, titleTableEvidence=title_records if title_from_texpack else [],')
p.write_text(s,encoding='utf-8')
p=Path('work/extractor/verify_app_package.py');s=p.read_text(encoding='utf-8')
s=s.replace('from PIL import Image','from PIL import Image\nimport struct\nfrom render_maps import unpack_tbl\nfrom native_labels import Decoder')
s=s.replace("    for item in evidence['maps']:", "    tbl=unpack_tbl((out/'originali/IT/FIELD/PANEL/ROADMAP/ROADMAP.TBL').read_bytes())\n    decoder=Decoder(out/'tool/P5R_EFIGS.tsv')\n    title_ftd=tbl['fld_texpack_title.ftd']\n    for item in evidence['maps']:")
s=s.replace("        if item.get('displayNameVerified'):", "        if item.get('titleTableEvidence'):\n            titles=[]\n            major,minor,layer=map(int,item['code'].split('_')[1:])\n            for ref in item['titleTableEvidence']:\n                at=ref['texpack_offset']\n                maj,minr,layers,_=struct.unpack_from('<4H',tbl['texpack.bin'],at)\n                assert (maj,minr)==(major,minor) and layer<layers\n                ix=struct.unpack_from('<H',tbl['texpack.bin'],at+52+layer*2)[0]\n                assert ix==ref['texelem_index']\n                tid=struct.unpack_from('<H',tbl['texelem.bin'],ix*16+6)[0]\n                assert tid==ref['area_title_index']\n                off=struct.unpack_from('>I',title_ftd,16+tid*4)[0]\n                label,unknown=decoder.decode(title_ftd[off+16:])\n                assert not unknown and label==ref['title']\n                if label not in ('???','NULL',''):titles.append(label)\n            assert set(titles)=={row['nome']}\n        elif item.get('displayNameVerified'):")
s=s.replace("            assert item['parentEvidence']['kind'] == 'resource-group-only'", "            assert item['parentEvidence']['kind'] in ('resource-group-only','native-dungeon-title')")
p.write_text(s,encoding='utf-8')
